-- =============================================================================
-- Pylna Residence — dane inwestycji (tabela pages, patrz db/schema.sql)
-- =============================================================================
--
-- Wygenerowane z analizy starego projektu kgd-group-deweloper:
--   src/components/templates/pylna-residence/**
--   src/data/pages/inwestycja/pylnaresidence/**
--
-- Uwagi:
--   - "Offert" (housesPoints) — 8 mieszkań (M 1..M 8) z placeholderowymi
--     metrażami/cenami: area=110m² dla wszystkich (opis inwestycji), gardenArea
--     w zakresie 100-400m² (jak w opisie), terraceArea=56.45m² dla każdego —
--     to STAŁA zaszyta w oryginalnym Offert.jsx (nie dane z API), zachowana 1:1.
--     Realne ceny/statusy do uzupełnienia w adminie.
--   - "features" w AboutUs — w źródle hotlinkowane do https://rudava-park.pl/upload/...
--     (zewnętrzna domena!). Zastąpione lokalnymi kopiami tych samych generycznych
--     ikon już zmigrowanymi przy rudava-park (icon-map/cube/garden/house.svg),
--     żeby nie zależeć od zewnętrznego API zgodnie z zasadami projektu.
--   - "HousePlanMap" nie ma komponentu w src/components/investments/pylna-residence/template.tsx —
--     dokładnie jak w starym projekcie (brak wpisu w template.js, sekcja się
--     nie renderowała) — dane (puste fields:{}) zostają w SQL dla ciągłości.
--   - Font "Melodrama Variable" (nagłówki slajdów w AboutUs) dodany do
--     src/lib/fonts.ts — w starym projekcie realnie wpięty (--font-melodrama),
--     w odróżnieniu od literalnej klasy "font-ranade" (bez "-variable"),
--     która w starym CSS nie miała odpowiadającego tokenu i renderowała się
--     fontem domyślnym — tak jak przy innych inwestycjach, tu też naprawione
--     na "font-ranade-variable" (jedyny realnie zdefiniowany token Ranade).
--
-- UPSERT (ON DUPLICATE KEY UPDATE) — bezpieczne przy ponownym imporcie.
--
-- Import: mysql -u UZYTKOWNIK -p NAZWA_BAZY < db/inwestycje/pylna-residence.sql
-- =============================================================================

INSERT INTO pages (slug, content) VALUES
  ('/inwestycja/pylnaresidence', '{"slug":"/inwestycja/pylnaresidence","parent":null,"template":"pylna-residence","title":{"value":"Pylna Residence - Nowoczesne Domy przy ul. Pylnej - Komfort Krakowa w Otoczeniu Natury","editable":true,"label":"Tytuł strony","type":"string"},"updatedAt":"2026-09-07","status":"published","nav":{"label":"Pylna Residence","order":9},"seo":{"title":{"value":"Pylna Residence – domy przy ul. Pylnej","editable":true,"label":"Tytuł SEO","type":"string"},"description":{"value":"Nowoczesne domy bliźniacze z prywatnymi ogrodami i tarasami na dachu. Wola Justowska, funkcjonalne układy i komfort blisko centrum Krakowa.","editable":true,"label":"Opis SEO","type":"string"},"keywords":["Pylna Residence","domy bliźniacze Kraków","ul. Pylna","Wola Justowska","domy z ogrodem","taras na dachu","nowe domy Kraków"],"canonical":"https://kgd-group.pl/inwestycja/pylnaresidence","robots":{"index":true,"follow":true},"author":"KGD Group","ogTitle":"Pylna Residence – domy przy ul. Pylnej","ogDescription":"Nowoczesne domy bliźniacze z prywatnymi ogrodami i tarasami na dachu. Wola Justowska, funkcjonalne układy i komfort blisko centrum Krakowa.","ogImage":"https://kgd-group.pl/assets/images/og-image-kgd.jpg","ogType":"website","ogUrl":"https://kgd-group.pl/inwestycja/pylnaresidence","ogSiteName":"KGD Group","ogLocale":"pl_PL","twitterCard":"summary_large_image","twitterTitle":"Pylna Residence – domy przy ul. Pylnej","twitterDescription":"Nowoczesne domy bliźniacze z prywatnymi ogrodami i tarasami na dachu. Wola Justowska, funkcjonalne układy i komfort blisko centrum Krakowa.","twitterImage":"https://kgd-group.pl/assets/images/og-image-kgd.jpg","language":"pl","structuredData":[{"type":"WebPage"}]},"sections":[{"id":"navbar","component":"Navbar","type":"section","label":"Nawigacja","fields":{"menu":{"value":[{"name":"Inwestycja","path":"#inwestycja"},{"name":"Lista mieszkań","path":"#mieszkania"},{"name":"Wizualizacje","path":"#wizualizacje"},{"name":"Lokalizacja","path":"#lokalizacja"},{"name":"Deweloper","path":"/"},{"name":"Kontakt","path":"#kontakt"}],"editable":true,"label":"Linki nawigacji","type":"table"},"phone":{"value":"12 352 15 00","editable":true,"label":"Telefon","type":"string"}}},{"id":"hero","component":"Hero","type":"section","label":"Hero","fields":{"header":{"value":"Pylna Residence","editable":true,"label":"Nagłówek","type":"string"},"subHeader":{"value":"Nowoczesne domy przy ul. Pylnej, zaprojektowane dla osób, które chcą łączyć wygodę życia w Krakowie z bliskością natury. Przestronne wnętrza, prywatne ogrody i spokojne otoczenie tworzą idealne miejsce do życia dla wymagających mieszkańców.","editable":true,"label":"Podtytuł","type":"string"}}},{"id":"aboutus","component":"AboutUs","type":"section","label":"O inwestycji","fields":{"eyebrow":{"value":"O INWESTYCJI","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Pylna Residence","editable":true,"label":"Nagłówek","type":"string"},"subHeader":{"value":"Pylna Residence to zespół 4 domów 2-lokalowych w zabudowie bliźniaczej, zlokalizowanych przy ul. Pylnej na Woli Justowskiej. Projekt powstał z myślą o osobach, które pragną mieszkać w zielonej części Krakowa, jednocześnie mając łatwy dostęp do centrum miasta, lotniska i głównych tras wylotowych.","editable":true,"label":"Podtytuł","type":"string"},"features":{"value":[{"icon":"/investments/pylna-residence/icons/icon-map.svg","text":"Prestiżowa lokalizacja Wola Justowska"},{"icon":"/investments/pylna-residence/icons/icon-cube.svg","text":"Funkcjonalne układy"},{"icon":"/investments/pylna-residence/icons/icon-garden.svg","text":"Naturalne materiały"},{"icon":"/investments/pylna-residence/icons/icon-house.svg","text":"Nowoczesna inwestycja w zielonym otoczeniu"}],"editable":true,"label":"Cechy inwestycji","type":"table"},"slides":{"value":["4 domy w zabudowie bliźniaczej - łącznie 8 mieszkań po 110 m²","Prywatne ogrody o powierzchni od 100 do 400 m²","Taras na dachu przy każdym domu - dodatkowa przestrzeń do odpoczynku"],"editable":true,"label":"Slajdy (przewijane hasła na tle wizualizacji)","type":"table"},"whyEyebrow":{"value":"DLACZEGO WARTO","editable":true,"label":"Nadtytuł (dlaczego warto)","type":"string"},"whyHeader":{"value":"Dlaczego warto wybrać naszą Inwestycje","editable":true,"label":"Nagłówek (dlaczego warto)","type":"string"},"whyItems":{"value":[{"icon":"home","text":"Nowoczesna inwestycja\\nw zielonym otoczeniu"},{"icon":"tree","text":"Blisko natury,\\n z dala od zgiełku"},{"icon":"wind","text":"Przestrzeń do życia\\ni oddechu"},{"icon":"diamond","text":"Miejsce z charakterem"}],"editable":true,"label":"Karty (dlaczego warto)","type":"table"},"bottomText":{"value":"Nowoczesna architektura, duże przeszklenia oraz prywatne ogrody sprawiają, że apartamenty są jasne, funkcjonalne i sprzyjają codziennemu wypoczynkowi. Przemyślany układ pomieszczeń zapewnia wyraźny podział na strefę dzienną i nocną, a przestrzeń można łatwo dopasować do potrzeb rodziny - od strefy relaksu po komfortowe miejsce do pracy w domu. Wszystkie domy w Pylna Residence mają taki sam, starannie zaprojektowany układ funkcjonalny, gwarantujący jednolity standard komfortu. Poszczególne lokale różnią się jedynie położeniem w obrębie inwestycji oraz wielkością ogrodu. Sprawdź w tabeli poniżej dostępność apartamentów i poznaj szczegóły interesującego Cię lokalu.","editable":true,"label":"Tekst dolny","type":"string"}}},{"id":"offert","component":"Offert","type":"section","label":"Oferta","fields":{"eyebrow":{"value":"OFERTA","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Poznaj naszą ofertę","editable":true,"label":"Nagłówek","type":"string"},"text":{"value":"Pylna Residence to eleganckie domy w zabudowie bliźniaczej, zlokalizowane przy ul. Pylnej w Krakowie. Każdy lokal oferuje przemyślany metraż, funkcjonalny układ pomieszczeń, duże przeszklenia oraz wyjście do prywatnego ogrodu. Dodatkowym atutem są przestronne tarasy na dachu, tworzące prywatną strefę relaksu z widokiem na otoczenie. Strefa dzienna na parterze łączy salon, jadalnię i kuchnię, stając się naturalnym sercem domu. Na piętrze zaplanowano sypialnie, łazienki oraz wielofunkcyjną przestrzeń, którą można zaaranżować jako gabinet, pokój dziecka lub garderobę.","editable":true,"label":"Tekst wprowadzający","type":"string"},"listEyebrow":{"value":"MIESZKANIA","editable":true,"label":"Nadtytuł listy","type":"string"},"listHeader":{"value":"Lista mieszkań","editable":true,"label":"Nagłówek listy","type":"string"},"listText":{"value":"Wszystkie domy w Pylna Residence mają ten sam, dopracowany metraż i układ funkcjonalny, dzięki czemu każdy lokal oferuje taki sam standard komfortu. Różnią się natomiast położeniem w obrębie inwestycji, wielkością ogrodu oraz ekspozycją okien.","editable":true,"label":"Tekst listy","type":"string"},"listSubText":{"value":"Sprawdź dostępność poszczególnych domów w tabeli poniżej i dowiedz się więcej, klikając w szczegóły wybranego lokalu.","editable":true,"label":"Podtekst listy","type":"string"},"standardHeader":{"value":"Standard wykończenia","editable":true,"label":"Nagłówek standardu","type":"string"},"standardText":{"value":"Nowoczesna forma, naturalne materiały i perfekcyjnie dopracowane detale - Pylna Residence zachwyca dziś i przez lata.","editable":true,"label":"Tekst standardu","type":"string"},"standardFile":{"value":"","editable":true,"label":"Plik standardu wykończenia (PDF)","type":"string"},"prospectusHeader":{"value":"Prospekt informacyjny","editable":true,"label":"Nagłówek prospektu","type":"string"},"prospectusText":{"value":"Cała inwestycja w jednym miejscu - standard i harmonogram oraz kwestie prawne. Poznaj Pylna Residence świadomie, zanim podejmiesz decyzję.","editable":true,"label":"Tekst prospektu","type":"string"},"prospectusFile":{"value":"","editable":true,"label":"Plik prospektu informacyjnego (PDF)","type":"string"},"houses":{"value":[{"unit":"M 1","rooms":"4","area":"110","gardenArea":"400",